&=4(\mathbf{a}\times \mathbf{c})-6(\mathbf{b}\times \mathbf{c}) \\ &=4(3\mathbf{i}-3\mathbf{j})-6(\mathbf{i}) \\ &=(12\mathbf{i}-12\mathbf{j})+(-6\mathbf{i}) \\ &=6\mathbf{i}-12\mathbf{j}
